<!-- components/asset/AssetList.vue -->
<template>
  <view class="asset-list">
    <view v-if="viewMode === 'grid'" class="grid-mode">
      <view class="grid-container">
        <view 
          v-for="(item, index) in filteredAssets" 
          :key="index" 
          class="asset-card"
          @click="goToDetail(item)"
        >
          <!-- 顶部：图标和天数 -->
          <view class="card-header">
            <view class="asset-icon">
              <text>📞</text>
            </view>
            <view class="days">{{ item.days }}天</view>
          </view>
          <!-- 中间：资产名称 -->
          <view class="asset-name">
            {{ item.name }}
          </view>
          <!-- 底部：金额和日均 -->
          <view class="card-body">
            <view class="price-row">
              <text class="price">¥{{ (item.price) }}</text>
              <text class="daily-avg">¥{{ (parseFloat(item.price) / item.days).toFixed(2) }}/天</text>
            </view>
          </view>
        </view>
      </view>
    </view>

    <view v-else class="list-mode">
      <view
        v-for="(item, index) in filteredAssets"
        :key="index"
        class="asset-item list-item"
        @click="goToDetail(item)"
      >
        <!-- 左侧图标 -->
        <view class="item-icon">
          <text>📞</text>
        </view>
        
        <!-- 中间内容 -->
        <view class="item-content">
          <view class="item-name">{{ item.name }}</view>
          <view class="item-price">
            <text class="price">¥{{ item.price }}</text>
            <text class="daily">¥{{ (parseFloat(item.price) / item.days).toFixed(2) }}/天</text>
          </view>
        </view>
        
        <!-- 右侧天数 -->
        <view class="item-days">
          {{ item.days }}天
        </view>
      </view>
    </view>
  </view>
</template>

<script setup>
import { computed } from 'vue'

const props = defineProps({
  assets: { type: Array, default: () => [] },
  viewMode: { type: String, default: 'grid' },
  filterStatus: { type: String, default: '全部' },
  filterCategory: { type: String, default: '全部' }
})

// 过滤资产列表：根据状态和分类筛选
const filteredAssets = computed(() => {
  return props.assets.filter(item => {
    return (
      (props.filterStatus === '全部' || item.status === props.filterStatus) &&
      (props.filterCategory === '全部' || item.category === props.filterCategory)
    )
  })
})

// 跳转到资产详情页
const goToDetail = (item) => {
  // 校验资产 ID 是否存在
  if (!item || !item.id) {
    uni.showToast({ title: '资产信息无效', icon: 'none' });
    return;
  }

  // 执行页面跳转
  uni.navigateTo({
    url: `/pages/asset/detail/detail?id=${item.id}`,
    fail: () => {
      uni.showToast({ title: '跳转失败', icon: 'none' });
    }
  });
};
</script>

